// The bundled graphic pack files (runtime/data/graphic_packs), as text compiled into the runtime:
// graphic_packs_data.cpp is generated by CMakeLists.txt. Paths are "<pack>/<file>".
#pragma once
#include <cstddef>

namespace graphic_packs {
struct EmbeddedFile {
    const char* path;
    const char* text;
};
extern const EmbeddedFile kFiles[];
extern const size_t kFileCount;
}  // namespace graphic_packs
